const fs = require('fs');

const defaults = { port: 3000, host: '127.0.0.1' };

const raw = fs.readFileSync('config.json', 'utf8');
const config = JSON.parse(raw || '{}');

const out = { ...defaults, ...config };

fs.writeFileSync('config.out.json', JSON.stringify(out, null, 2) + '\n');

console.log('wrote config.out.json');

